SELECT MAX(SKUKEY) AS SKUKEY ,MAX(DESC01) AS DESC01 ,MAX(QTYASN) AS ASNQTY ,MAX(BOXQTY) AS BOXQTY ,MAX(REMQTY) AS REMQTY ,MAX(LOTA03) AS LOTA03 ,MAX(NAME01) AS LOTA03NM ,MAX(LOTA07) AS LOTA07 ,MAX(LOTA07NM) AS LOTA07NM ,MAX(SEBELN) AS SEBELN ,MAX(LOTA11) AS LOTA11 ,MAX(LOTA13) AS LOTA13 ,MAX(ASNDKY) AS ASNDKY FROM V_PDA_ASNDH WHERE 1=1
AND ASNDKY = #{COLTEXT}
AND SKUKEY = #{COLTEXT}
AND DESC01 like '%${COLTEXT}%'
GROUP BY ASNDKY

SELECT COUNT(*) AS CNT FROM RCFAIL
 WHERE SKUKEY= #{SKUKEY}
   AND ASNDKY= #{ASNDKY}
   AND ASNDIT= #{ASNDIT}

SELECT LOCAKY, SKUKEY, DESC01, AREAKY, ZONEKY FROM STKKY WHERE 1=1
AND LOCAKY = #{COLTEXT}
AND SKUKEY = #{COLTEXT}
AND DESC01 like '%${COLTEXT}%'

SELECT COUNT(*) AS CNT
 FROM LOCMA
 WHERE LOCAKY = #{LOCAKY}

SELECT MAX(SKUKEY) AS SKUKEY
  FROM STKKY
 WHERE LOTNUM = #{LOTNUM}

SELECT SKUKEY ,DESC01 ,TRNQTY ,LOCASR ,SHPOKY ,TASKKY FROM V_PDA_ORDER_TASDH WHERE 1=1
AND SHPOKY = #{COLTEXT}
AND TASKKY = #{COLTEXT}
AND SKUKEY = #{COLTEXT}
AND DESC01 like '%' || #{COLTEXT} || '%'

SELECT SVBELN, SPOSNR, SEBELN, SEBELP, SZMBLNO, NAME01, SKUKEY, DESC01, LOTA01, LOTA02, LOTA03, LOTA04, LOTA05, LOTA06, LOTA07, LOTA08, LOTA09, LOTA10, LOTA11, LOTA12, LOTA13, LOTA14, LOTA15, LOCATG, LOCASR, TRNQTY, INOQTY, TRUNC(TRNQTY/OUTDMT, 0) AS BOXCNT, MOD(TRNQTY, OUTDMT) AS PIECE, UOMKEY, SDUOKY, WAREKY, OWNRKY, AREAKY, STKNUM, TASKKY, TASKIT, SHPOKY, SHPOIT, JOBTYP, PTNRKY, OUTDMT, (SELECT LOTNUM FROM TASDI WHERE TASDI.TASKKY=V_PDA_ORDER_TASDH.TASKKY AND TASDI.TASKIT=V_PDA_ORDER_TASDH.TASKIT) AS LOTNUM, ENABLE FROM V_PDA_ORDER_TASDH WHERE 1=1
AND SHPOKY = #{SHPOKY}
AND TASKKY = #{TASKKY}
AND SKUKEY = #{SKUKEY}
AND STKNUM = #{STKNUM}

SELECT SKUKEY ,DESC01 ,TRNQTY ,LOCASR ,TASKKY FROM V_PDA_TASK_TASDH WHERE 1=1
AND TASKKY = #{COLTEXT}
AND SKUKEY = #{COLTEXT}
AND DESC01 like '%' || #{COLTEXT} || '%'

SELECT SKUKEY ,DESC01 ,TRNQTY ,LOCASR ,SHPOKY ,TASKKY ,STKNUM FROM V_PDA_ORDER_TASDH WHERE 1=1
AND STKNUM <> ' '
AND STKNUM = #{COLTEXT}
AND SHPOKY = #{COLTEXT}
AND TASKKY = #{COLTEXT}
AND SKUKEY = #{COLTEXT}
AND DESC01 like '%' || #{COLTEXT} || '%'

mapper.update:
UPDATE TASDI SET
	LOCATG = #{LOCATG} ,
	LMODAT = TO_CHAR(SYSDATE, 'YYYYMMDD'),
	LMOTIM = TO_CHAR(SYSDATE, 'HH24MISS'),
	LMOUSR = #{SES_USER_ID}
 WHERE 1=1
   AND TASKKY = #{TASKKY}
   AND TASKIT = #{TASKIT}

mapper.select:
SELECT ' ' AS AUTLOC, '0' AS QTSPMI, '0' AS QTSPMO, ' ' AS PQTY01, ' ' AS PQTY02, ' ' AS PQTY03, ' ' AS PQTY04, ' ' AS PQTY05, ' ' AS PQTY06, I.PHYIKY AS PHYIKY, I.PHYIIT AS PHYIIT, I.RSNADJ AS RSNADJ, I.STOKKY AS STOKKY, I.LOTNUM AS LOTNUM, I.LOCAKY AS LOCAKY, I.TRNUID AS TRNUID, I.SECTID AS SECTID, I.PACKID AS PACKID, I.QTADJU AS QTADJU, I.QTYPDA AS QTYPDA, I.QTBLKD AS QTBLKD, I.QTYUOM AS QTYUOM, I.TRUNTY AS TRUNTY, I.MEASKY AS MEASKY, I.UOMKEY AS UOMKEY, I.QTPUOM AS QTPUOM, I.DUOMKY AS DUOMKY, I.QTDUOM AS QTDUOM, I.SUBSIT AS SUBSIT, I.SUBSFL AS SUBSFL, I.REFDKY AS REFDKY, I.REFDIT AS REFDIT, I.REFCAT AS REFCAT, I.OWNRKY AS OWNRKY, I.SKUKEY AS SKUKEY, I.LOTA01 AS LOTA01, I.LOTA02 AS LOTA02, I.LOTA03 AS LOTA03, I.LOTA04 AS LOTA04, I.LOTA05 AS LOTA05, I.LOTA06 AS LOTA06, I.LOTA07 AS LOTA07, I.LOTA08 AS LOTA08, I.LOTA09 AS LOTA09, I.LOTA10 AS LOTA10, I.LOTA11 AS LOTA11, I.LOTA12 AS LOTA12, I.LOTA13 AS LOTA13, I.LOTA14 AS LOTA14, I.LOTA15 AS LOTA15, I.LOTA16 AS LOTA16, I.LOTA17 AS LOTA17, I.LOTA18 AS LOTA18, I.LOTA19 AS LOTA19, I.LOTA20 AS LOTA20, I.AWMSNO AS AWMSNO, I.AREAKY AS AREAKY, I.DESC01 AS DESC01, I.DESC02 AS DESC02, I.ASKU01 AS ASKU01, I.ASKU02 AS ASKU02, I.ASKU03 AS ASKU03, I.ASKU04 AS ASKU04, I.ASKU05 AS ASKU05, I.EANCOD AS EANCOD, I.GTINCD AS GTINCD, I.SKUG01 AS SKUG01, I.SKUG02 AS SKUG02, I.SKUG03 AS SKUG03, I.SKUG04 AS SKUG04, I.SKUG05 AS SKUG05, I.GRSWGT AS GRSWGT, I.NETWGT AS NETWGT, I.WGTUNT AS WGTUNT, I.LENGTH AS LENGTH, I.WIDTHW AS WIDTHW, I.HEIGHT AS HEIGHT, I.CUBICM AS CUBICM, I.CAPACT AS CAPACT, I.WORKID AS WORKID, I.WORKNM AS WORKNM, I.HHTTID AS HHTTID, I.SMANDT AS SMANDT, I.SEBELN AS SEBELN, I.SEBELP AS SEBELP, I.SZMBLNO AS SZMBLNO, I.SZMIPNO AS SZMIPNO, I.STRAID AS STRAID, I.SVBELN AS SVBELN, I.SPOSNR AS SPOSNR, I.STKNUM AS STKNUM, I.STPNUM AS STPNUM, I.SWERKS AS SWERKS, I.SLGORT AS SLGORT, I.SDATBG AS SDATBG, I.STDLNR AS STDLNR, I.SSORNU AS SSORNU, I.SSORIT AS SSORIT, I.SMBLNR AS SMBLNR, I.SZEILE AS SZEILE, I.SMJAHR AS SMJAHR, I.SXBLNR AS SXBLNR, I.SAPSTS AS SAPSTS, I.QTSPHY AS QTYSTL, I.QTSIWH AS QTSIWH, I.QTSPHY AS QTSPHY, I.QTSALO AS QTSALO, I.QTSIWH-GREATEST(I.QTSALO, I.QTSPMO) - I.QTBLKD AS USEQTY, H.INDDCL AS INDDCL, H.PHSCTY AS PHSCTY, H.WAREKY AS WAREKY, H.DOCCAT AS DOCCAT, H.PHSCTY AS PHSCTY, H.DOCDAT AS DOCDAT, S.ZONEKY AS ZONEKY, (SELECT COUNT(*) FROM PHYDI IL WHERE I.PHYIKY = IL.PHYIKY AND SUBSTR(I.PHYIIT,0,5) = SUBSTR(IL.PHYIIT,0,5) AND SUBSTR(IL.PHYIIT,6,1) != '0') AS CNT FROM PHYDH H, PHYDI I, LOCMA S WHERE 1=1
AND H.PHYIKY = #{PHYIKY}
AND H.CREUSR LIKE '%' || #{CREUSR} ||'%'
AND I.LOCAKY = #{LOCAKY}
AND H.PHYIKY = #{COLTEXT}
AND I.AREAKY = #{COLTEXT}
AND S.ZONEKY = #{COLTEXT}
AND I.LOCAKY = #{COLTEXT}
AND I.SKUKEY = #{COLTEXT}
AND I.DESC01 like '%${COLTEXT}%'
AND H.PHYIKY = I.PHYIKY AND H.WAREKY = S.WAREKY AND I.LOCAKY = S.LOCAKY AND INDDCL ! = 'V' ORDER BY I.PHYIKY, I.PHYIIT

mapper.update:
UPDATE PHYDI SET
	RSNADJ = #{RSNADJ},

	QTYPDA = #{QTYPDA}
WHERE PHYIKY = #{PHYIKY}
	AND PHYIIT = #{PHYIIT}

mapper.delete:
DELETE FROM RCFAIL
WHERE 1 = 1
  AND TMPNUM = #{TMPNUM}

mapper.select:
SELECT ' ' AS RECVKY, (SELECT SHORTX FROM DOCCM WHERE DOCCAT = '100') AS DOCCATNM, '100' AS DOCCAT, TO_CHAR(SYSDATE,'YYYYMMDD') AS DOCDAT, TO_CHAR(SYSDATE,'YYYYMMDD') AS ARCPTD, 'NEW' AS STATDO, ' ' AS DOCTXT, ' ' AS RECVIT, (
SELECT SKUKEY FROM LOTAT WHERE LOTNUM = #{SKUKEY}
SELECT SKUKEY FROM SKUMA WHERE 1=1 AND EANCOD = #{EANCOD}
) AS SKUKEY,
(
SELECT SKUKEY FROM LOTAT WHERE LOTNUM = #{SKUKEY}
SELECT EANCOD FROM SKUMA WHERE 1=1 AND EANCOD = #{EANCOD}
) AS EANCOD,
(SELECT DESC01 FROM SKUMA WHERE 1=1
AND SKUKEY = ( SELECT SKUKEY FROM LOTAT WHERE LOTNUM = #{SKUKEY}
)
AND EANCOD = #{EANCOD}
) AS DESC01,
'' AS QTYRCV, '' AS LOCAKY, ' ' AS LOTA01, '33' AS LOTA02, ' ' AS LOTA03, ' ' AS LOTA05, '00' AS LOTA06, ' ' AS LOTA08, ' ' AS LOTA09, ' ' AS LOTA11, ' ' AS LOTA13, 'SLC' AS LOTA14, ' ' AS UOMKEY, ' ' AS DUOMKY, ' ' AS QTDUOM, ' ' AS BOXQTY, ' ' AS REMQTY, ' ' AS QTPUOM, TO_CHAR(SYSDATE,'YYYYMMDD') AS CREDAT, #{SES_USER_ID} AS CREUSR, (SELECT NMLAST FROM USRMA WHERE USERID =#{SES_USER_ID}) AS CUSRNM, TO_CHAR(SYSDATE,'YYYYMMDD') AS LMODAT, #{SES_USER_ID} AS LMOUSR, (SELECT NMLAST FROM USRMA WHERE USERID =#{SES_USER_ID}) AS LUSRNM FROM DUAL WHERE 1 = 1

