, SKUG05 AS SKUG05, GRSWGT AS GRSWGT, NETWGT AS NETWGT, WGTUNT AS WGTUNT, LENGTH AS LENGTH, WIDTHW AS WIDTHW, HEIGHT AS HEIGHT, CUBICM AS CUBICM, CAPACT AS CAPACT, ZONEKY AS ZONEKY, TKZONE AS TKZONE, AREAKY AS AREAKY, SMANDT AS SMANDT, SEBELN AS SEBELN, SEBELP AS SEBELP, SZMBLNO AS SZMBLNO, SZMIPNO AS SZMIPNO, STRAID AS STRAID, SVBELN AS SVBELN, SPOSNR AS SPOSNR, STKNUM AS STKNUM, STPNUM AS STPNUM, SWERKS AS SWERKS, SLGORT AS SLGORT, SDATBG AS SDATBG, STDLNR AS STDLNR, SSORNU AS SSORNU, SSORIT AS SSORIT, SMBLNR AS SMBLNR, SZEILE AS SZEILE, SMJAHR AS SMJAHR, SXBLNR AS SXBLNR, SAPSTS AS SAPSTS, SUBSTR(CREDAT||CRETIM, 1, 8) AS CREDAT, SUBSTR(CREDAT||CRETIM, 9, 6) AS CRETIM, CREUSR AS CREUSR FROM STKKY, (SELECT * FROM BUYER WHERE (SKUKEY = #{SKUKEY} OR MATNR = #{SKUKEY}) AND ROWNUM = 1) BM WHERE STKKY.OWNRKY = BM.OWNRKY(+) AND STKKY.SKUKEY = BM.SKUKEY(+) AND QTSIWH-GREATEST(QTSALO, QTSPMO) - QTSBLK != 0 AND QTSIWH > 0 AND AREAKY NOT IN ('SYS', 'SHP')
