SELECT DISTINCT RI.RECVKY FROM RECDI RI WHERE 1 = 1
AND RI.SEBELN = (SELECT MAX(EBELN) FROM IFWMS103 WHERE USRID2 = (SELECT MAX(SVBELN) FROM TASDI WHERE DOORKY = #{DOCUKY}))
AND RI.LOTA07 = #{DOCUKY}
UNION ALL
SELECT #{DOCUKY} FROM DUAL )

SELECT a.SEQ, a.INSPR_DT, a.INSPR_TM, a.INSPR_NM, a.INSTD_CFG, a.MATNR, (SELECT MATNR_NM FROM TB_QLT030 WHERE MATNR = a.MATNR) AS MATNR_NM, (SELECT BS_WGT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS BS_WGT, (SELECT CLSF_STCNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_STCNT, (SELECT CLSF_MCNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_MCNT, (SELECT CLSF_CTCNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_CTCNT, (SELECT CLSF_ROLL_CNT FROM TB_QLT030 WHERE MATNR = a.MATNR) AS CLSF_ROLL_CNT, a.MACH_CD, a.PART_DIV, a.CREATEUSER, a.CREATEDATE as CLSF_INPUTDT, a.UPDATEUSER, a.UPDATEDATE as CLSF_MODDT, a.RMK1 AS A_RMK1, a.RMK2 AS A_RMK2, a.RMK3 AS A_RMK3, b.SEQ, b.P_SEQ, b.CLSF_LARGE, b.CLSF_SMALL, b.CLSF_RST_VAL, b.RMK1 AS B_RMK1, b.RMK2 AS B_RMK2, b.RMK3 AS B_RMK3 FROM TB_QLT031 a, TB_QLT032 b WHERE a.SEQ = b.P_SEQ
