UPDATE TB_QLT021
SET MSRM_DATE = TO_DATE(#{NEW_MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
  , UPDDATE = SYSDATE
  , UPDID = #{REGID}
WHERE WERKS = #{WERKS}
  AND MSRM_DATE = TO_DATE(#{OLD_MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
  AND PRC_SEQNO = #{PRC_SEQNO}
  AND INSP_ITEM_GRP_CD = #{INSP_ITEM_GRP_CD}

UPDATE TB_INV001
SET MSRM_DATE = TO_DATE(#{NEW_MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
  , INSPR_ID = #{REGID}
  , PRC_SEQNO = #{PRC_SEQNO}
  , UPDDATE = SYSDATE
  , UPDID = #{REGID}
WHERE WERKS = #{WERKS}
  AND IND_BCD = #{IND_BCD}

UPDATE TB_QLT024
SET MSRM_DATE = TO_DATE(#{NEW_MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
  , UPDDATE = SYSDATE
  , UPDID = #{REGID}
WHERE WERKS = #{WERKS}
  AND IND_BCD = #{IND_BCD}

MERGE INTO tb_qlt021 T
	USING dual
	on (
		T.WERKS = #{WERKS}
			AND T.MSRM_DATE = TO_DATE(#{NEW_MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS')
			AND T.PRC_SEQNO = #{PRC_SEQNO}
			AND T.INSP_ITEM_GRP_CD = #{INSP_ITEM_GRP_CD}
			AND T.INSP_ITEM_CD = #{INSP_ITEM_CD}
		)
	WHEN MATCHED THEN
		UPDATE SET
			T.RST_VAL = #{RST_VAL}
			, T.UPDDATE = SYSDATE
			, T.UPDID	= #{REGID}
	WHEN NOT MATCHED THEN
		INSERT (
				WERKS, MATNR, MSRM_DATE, PRC_SEQNO, INSP_ITEM_GRP_CD, INSP_ITEM_CD, RST_VAL, REGDATE, REGID
			) VALUES (#{WERKS}, #{MATNR}, TO_DATE(#{NEW_MSRM_DATE}, 'YYYY-MM-DD HH24:MI:SS'), #{PRC_SEQNO}, #{INSP_ITEM_GRP_CD},
					  #{INSP_ITEM_CD}, #{RST_VAL}, SYSDATE, #{REGID})
